"""Pre-compute taint metadata (``TAINT``) from Python function bodies. JS/TS: Phase 1b."""
from __future__ import annotations

import ast
import re
from collections import deque
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Optional

import networkx as nx

from depos.analysis.cfg import python_cfg as _cfg
from depos.analysis.run_context import RunContext
from depos.analysis.schemas import SeamEdge, SemanticEdgeMetadata, TaintEdge

_TAINT_SINKS = re.compile(
    r"(execute\(\s*|\.execute\(\s*|raw\(|os\.system|subprocess|eval\(|eval\s*\(|exec\()",
    re.I,
)
_MAX_INTERPROCEDURAL_HOPS = 4
_MAX_INTERPROCEDURAL_BRANCHES = 64


def _is_call_edge(data: dict[str, Any]) -> bool:
    return str(data.get("relation") or data.get("type") or "").casefold() == "calls"


def _incoming_callers(graph: nx.DiGraph, node_id: str) -> tuple[str, ...]:
    if node_id not in graph:
        return ()
    callers: set[str] = set()
    for u, _, data in graph.in_edges(node_id, data=True):
        if _is_call_edge(data):
            callers.add(str(u))
    return tuple(sorted(callers))


def _is_entry_like_scope(graph: nx.DiGraph, node_id: str) -> bool:
    attrs = graph.nodes.get(node_id) or {}
    if attrs.get("is_fastapi_route"):
        return True
    kind = str(
        attrs.get("node_kind")
        or attrs.get("entity_kind")
        or attrs.get("kind")
        or attrs.get("ast_kind")
        or ""
    ).casefold()
    if kind in {"next_route", "next_middleware", "openapi_operation"}:
        return True
    rel = str(attrs.get("source_file") or "").replace("\\", "/").casefold()
    return rel.endswith(("/route.py", "/route.ts", "/route.tsx", "/route.js", "/route.jsx"))


def _call_origin_score(graph: nx.DiGraph, node_id: str) -> int:
    if _is_entry_like_scope(graph, node_id):
        return 0
    if not _incoming_callers(graph, node_id):
        return 1
    return 2


def _interprocedural_taint_path(
    graph: nx.DiGraph, scope_id: str, source_node: str, sink_node: str
) -> list[str]:
    queue = deque([(scope_id, [scope_id])])
    best: list[str] | None = None
    best_score: tuple[int, int, str] | None = None
    seen_depth: dict[str, int] = {scope_id: 0}
    branches = 0

    while queue and branches < _MAX_INTERPROCEDURAL_BRANCHES:
        current, path = queue.popleft()
        depth = len(path) - 1
        if depth:
            score = (_call_origin_score(graph, path[0]), depth, "\0".join(path))
            if best_score is None or score < best_score:
                best = path
                best_score = score
                if score[0] == 0:
                    break
        if depth >= _MAX_INTERPROCEDURAL_HOPS:
            continue
        for caller in _incoming_callers(graph, current):
            next_depth = depth + 1
            if caller in path or seen_depth.get(caller, next_depth + 1) <= next_depth:
                continue
            seen_depth[caller] = next_depth
            queue.append((caller, [caller, *path]))
            branches += 1
            if branches >= _MAX_INTERPROCEDURAL_BRANCHES:
                break

    if not best:
        return [source_node, sink_node]
    return [source_node, *best, sink_node]


def seam_edge_ids_for_scope(graph: nx.DiGraph, scope_id: str) -> list[str]:
    """Incident seam edge ids for *scope_id* (read-only)."""
    ids: list[str] = []
    seen: set[str] = set()
    for u, v, data in graph.edges(data=True):
        if u != scope_id and v != scope_id:
            continue
        is_seam = bool(data.get("seam")) or (
            data.get("source_system") and data.get("target_system")
        )
        if not is_seam:
            continue
        eid = str(data.get("edge_id") or f"{u}->{v}")
        if eid not in seen:
            seen.add(eid)
            ids.append(eid)
    return ids


@dataclass
class TaintScopeWork:
    """Deferred taint mutations for one scope (Phase 8: compute in parallel, apply serially)."""

    scope_id: str
    seam_edge_ids: list[str]
    new_nodes: list[tuple[str, dict[str, Any]]] = field(default_factory=list)
    new_edges: list[tuple[str, str, dict[str, Any]]] = field(default_factory=list)
    typed: list[TaintEdge] = field(default_factory=list)
    row_extras: list[dict[str, Any] | None] | None = None


def taint_graph_fingerprint(graph: nx.DiGraph, scope_id: str) -> str:
    """Stable digest of graph-local inputs that affect taint for *scope_id*."""

    from depos.cache import stable_hash

    return stable_hash(
        {
            "seams": seam_edge_ids_for_scope(graph, scope_id),
            "callers": list(_incoming_callers(graph, scope_id)),
        }
    )


def taint_work_cache_payload(work: TaintScopeWork) -> dict[str, Any]:
    return {
        "scope_id": work.scope_id,
        "seam_edge_ids": list(work.seam_edge_ids),
        "new_nodes": [{"id": nid, "attrs": nattr} for nid, nattr in work.new_nodes],
        "new_edges": [{"u": u, "v": v, "attrs": ed} for u, v, ed in work.new_edges],
        "typed": [te.model_dump(mode="json") for te in work.typed],
        "row_extras": work.row_extras,
    }


def taint_work_from_cache_payload(raw: dict[str, Any]) -> TaintScopeWork | None:
    if not isinstance(raw, dict) or "scope_id" not in raw:
        return None
    try:
        typed = [TaintEdge.model_validate(x) for x in raw.get("typed") or []]
        new_nodes = [
            (str(x["id"]), dict(x["attrs"]))  # type: ignore[index]
            for x in raw.get("new_nodes") or []
        ]
        new_edges = [
            (str(x["u"]), str(x["v"]), dict(x["attrs"]))  # type: ignore[index]
            for x in raw.get("new_edges") or []
        ]
    except (KeyError, TypeError, ValueError):
        return None
    return TaintScopeWork(
        str(raw["scope_id"]),
        list(raw.get("seam_edge_ids") or []),
        new_nodes=new_nodes,
        new_edges=new_edges,
        typed=typed,
        row_extras=raw.get("row_extras"),
    )


def apply_taint_scope_work(graph: nx.DiGraph, work: TaintScopeWork) -> list[dict[str, Any]]:
    """Apply deferred taint nodes/edges and ``taint_edges`` rows (main thread only)."""
    if work.scope_id in graph:
        graph.nodes[work.scope_id]["seam_edge_ids"] = work.seam_edge_ids
    for nid, nattr in work.new_nodes:
        if nid not in graph:
            graph.add_node(nid, **nattr)
    for u, v, ed in work.new_edges:
        if not graph.has_edge(u, v):
            graph.add_edge(u, v, **ed)
    if not work.typed:
        return []
    return _append_taint_graph_outputs(
        graph, work.typed, row_extras=work.row_extras or [None] * len(work.typed)
    )


def compute_python_taint_work(
    graph: nx.DiGraph,
    scope_id: str,
    attrs: dict[str, Any],
    *,
    run_context: RunContext,
    repo_root: Optional[Path] = None,
) -> TaintScopeWork:
    """Compute taint for one Python scope without mutating *graph*."""
    seam_ids = seam_edge_ids_for_scope(graph, scope_id)
    attrs_eff = {**attrs, "seam_edge_ids": seam_ids}
    seam_index = run_context.seam_edge_index
    out_typed: list[TaintEdge] = []
    new_nodes: list[tuple[str, dict[str, Any]]] = []
    new_edges: list[tuple[str, str, dict[str, Any]]] = []

    rel = str(attrs_eff.get("source_file") or "")
    start = int(
        (attrs_eff.get("span") or {}).get("start", {}).get("line")
        or attrs_eff.get("start_line")
        or attrs_eff.get("lineno")
        or 0
    )
    if not rel or not start:
        return TaintScopeWork(scope_id, seam_ids)

    qn = str(attrs_eff.get("qualname") or attrs_eff.get("name") or "")
    source_hints: list[str] = [h for h in (qn, rel) if h]
    src = _cfg._read_source(repo_root, rel)  # noqa: SLF001
    if not src:
        return TaintScopeWork(scope_id, seam_ids)
    try:
        tree = ast.parse(src, filename=rel)
    except SyntaxError:
        return TaintScopeWork(scope_id, seam_ids)
    if not isinstance(tree, ast.Module):
        return TaintScopeWork(scope_id, seam_ids)
    fn = _cfg._find_function(  # noqa: SLF001
        tree, qualname=qn, start_line=start, end_line=int(attrs_eff.get("end_line") or start)
    ) or _cfg._fallback_by_line(  # noqa: SLF001
        tree, start, int(attrs_eff.get("end_line") or start + 500)
    )
    if not fn or not isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)):
        return TaintScopeWork(scope_id, seam_ids)

    eids: list[str] = list(seam_ids)
    seam_list = _seam_schemas_for_ids(graph, eids, seam_index)
    has_http = bool(attrs_eff.get("http_call_sites"))
    for node in fn.body:
        chunk = ast.get_source_segment(src, node) or ""
        m = _TAINT_SINKS.search(chunk)
        if not m:
            continue
        line = int(getattr(node, "lineno", 0) or 0)
        u, v = f"taint:src:{scope_id}", f"taint:sink:{scope_id}:L{line}"
        new_nodes.append((u, {"type": "taint_endpoint", "label": "taint_source"}))
        new_nodes.append((v, {"type": "taint_endpoint", "label": "taint_sink"}))
        te = TaintEdge(
            source_node=u,
            sink_node=v,
            intermediate_path=_interprocedural_taint_path(graph, scope_id, u, v),
            crosses_seam=has_http or bool(seam_list),
            seam_edges_crossed=seam_list,
            source_chain=f"{rel}:{line}",
            sink_pattern=m.group(0).strip()[:64],
            source_hints=source_hints,
            scope=scope_id,
            line=line,
        )
        out_typed.append(te)
        new_edges.append(
            (
                u,
                v,
                {
                    "type": "TAINT",
                    "taint_line": line,
                    "sink_pattern": te.sink_pattern,
                    "path": f"{rel}:{line}",
                },
            )
        )
    return TaintScopeWork(
        scope_id,
        seam_ids,
        new_nodes=new_nodes,
        new_edges=new_edges,
        typed=out_typed,
        row_extras=None,
    )


def _find_edge_by_eid(
    graph: nx.DiGraph, eid: str
) -> Optional[tuple[str, str, dict[str, Any]]]:
    for u, v, data in graph.edges(data=True):
        cur = str(data.get("edge_id") or f"{u}->{v}")
        if cur == eid:
            return u, v, data
    return None


def _seam_schemas_for_ids(
    graph: nx.DiGraph, edge_ids: list[str], seam_edge_index: dict[str, Any]
) -> list[SeamEdge]:
    out: list[SeamEdge] = []
    for eid in edge_ids:
        rec: Any = seam_edge_index.get(eid)
        if isinstance(rec, SeamEdge):
            out.append(rec)
            continue
        found = _find_edge_by_eid(graph, eid)
        if not found:
            continue
        u, v, data = found
        rel = str(data.get("relation") or data.get("label") or "edge")
        seam_info = dict(data.get("seam") or {})
        try:
            metadata = SemanticEdgeMetadata.model_validate(
                {k2: v2 for k2, v2 in data.items() if k2 != "relation"}
            )
        except Exception as e:  # noqa: BLE001
            import logging
            logging.getLogger(__name__).warning("Failed to validate SemanticEdgeMetadata: %s", e)
            metadata = SemanticEdgeMetadata()
        out.append(
            SeamEdge(
                edge_id=eid,
                source=u,
                target=v,
                relation=rel,
                source_language=str(seam_info.get("source_language") or ""),
                target_language=str(seam_info.get("target_language") or ""),
                pattern=str(seam_info.get("pattern") or "unknown"),
                contract_defined=bool(seam_info.get("contract_defined", False)),
                contract_verified=bool(seam_info.get("contract_verified", False)),
                metadata=metadata,
            )
        )
    return out


def _append_taint_graph_outputs(
    graph: nx.DiGraph,
    typed: list[TaintEdge],
    *,
    row_extras: list[dict[str, Any] | None] | None = None,
) -> list[dict[str, Any]]:
    """Write ``taint_edges`` (typed :class:`TaintEdge` list)."""
    if not typed:
        return []
    graph.graph.setdefault("taint_edges", []).extend(typed)
    out_rows: list[dict[str, Any]] = []
    for i, te in enumerate(typed):
        d = te.model_dump(mode="json")
        d["type"] = "TAINT"
        extra = (row_extras or [None] * len(typed))[i]
        if extra:
            d.update(extra)
        out_rows.append(d)
    return out_rows


def taint_for_python_scope(
    graph: nx.DiGraph,
    scope_id: str,
    attrs: dict[str, Any],
    *,
    run_context: RunContext,
    repo_root: Optional[Path] = None,
) -> list[dict[str, Any]]:
    """When a taint sink appears in a function body, add a graph edge and return rows.

    Emits :class:`TaintEdge` into ``graph.graph["taint_edges"]``.
    """
    work = compute_python_taint_work(
        graph, scope_id, attrs, run_context=run_context, repo_root=repo_root
    )
    return apply_taint_scope_work(graph, work)


_JSTS_TAINT_SINKS = re.compile(
    r"(eval\s*\(|innerHTML|child_process|\.exec\(\s*|execute\(\s*|`select\s)",
    re.I,
)
_JSTS_TAINT_SRC = re.compile(
    r"req\.(query|body|params|cookies|headers)|document\.location|location\.search|getParameter\s*\(",
    re.I,
)


def compute_jsts_taint_work(
    graph: nx.DiGraph,
    scope_id: str,
    attrs: dict[str, Any],
    *,
    run_context: RunContext,
    repo_root: Optional[Path] = None,
) -> TaintScopeWork:
    """Compute JS/TS taint for one scope without mutating *graph*."""
    from tree_sitter import Parser

    from depos.analysis.cfg.jsts import (
        _find_innermost_function,
        _get_function_body,
        _load_language_for_path,
        read_source_bytes,
    )

    seam_ids = seam_edge_ids_for_scope(graph, scope_id)
    attrs_eff = {**attrs, "seam_edge_ids": seam_ids}
    seam_index = run_context.seam_edge_index
    seam_list = _seam_schemas_for_ids(graph, seam_ids, seam_index)
    has_http = bool(attrs_eff.get("http_call_sites"))

    rel = str(attrs_eff.get("source_file") or "")
    start = int(
        (attrs_eff.get("span") or {}).get("start", {}).get("line")
        or attrs_eff.get("start_line")
        or attrs_eff.get("lineno")
        or 0
    )
    if not rel or not start:
        return TaintScopeWork(scope_id, seam_ids)
    raw = read_source_bytes(repo_root, rel)
    if not raw:
        return TaintScopeWork(scope_id, seam_ids)
    try:
        lang = _load_language_for_path(rel)
        tree = Parser(lang).parse(raw)
    except Exception as e:  # noqa: BLE001
        import logging
        logging.getLogger(__name__).warning("Failed to parse JS/TS scope %s: %s", rel, e)
        return TaintScopeWork(scope_id, seam_ids)
    fn = _find_innermost_function(tree.root_node, start)
    if fn is None:
        return TaintScopeWork(scope_id, seam_ids)
    body = _get_function_body(fn)
    if body is None:
        return TaintScopeWork(scope_id, seam_ids)
    text = raw[int(body.start_byte) : int(body.end_byte)].decode("utf-8", errors="replace")
    sink_m = _JSTS_TAINT_SINKS.search(text)
    js_sources = [x.group(0) for x in _JSTS_TAINT_SRC.finditer(text)]
    if not sink_m and not js_sources:
        return TaintScopeWork(scope_id, seam_ids)
    line = int(body.start_point[0]) + 1
    u, v = f"taint:src:{scope_id}", f"taint:sink:{scope_id}:L{line}"
    te = TaintEdge(
        source_node=u,
        sink_node=v,
        intermediate_path=_interprocedural_taint_path(graph, scope_id, u, v),
        crosses_seam=has_http or bool(seam_list),
        seam_edges_crossed=seam_list,
        source_chain=f"{rel}:{line}",
        sink_pattern=(sink_m.group(0).strip()[:64] if sink_m else "source_only"),
        source_hints=list(js_sources),
        scope=scope_id,
        line=line,
    )
    return TaintScopeWork(
        scope_id,
        seam_ids,
        new_nodes=[
            (u, {"type": "taint_endpoint", "label": "taint_source"}),
            (v, {"type": "taint_endpoint", "label": "taint_sink"}),
        ],
        new_edges=[
            (
                u,
                v,
                {
                    "type": "TAINT",
                    "taint_line": line,
                    "sink_pattern": te.sink_pattern,
                    "path": f"{rel}:{line}",
                },
            )
        ],
        typed=[te],
        row_extras=[{"js_sources": js_sources}],
    )


def taint_for_jsts_scope(
    graph: nx.DiGraph,
    scope_id: str,
    attrs: dict[str, Any],
    *,
    run_context: RunContext,
    repo_root: Optional[Path] = None,
) -> list[dict[str, Any]]:
    """Heuristic taint for JS/TS: known sources + known sinks in function text (Phase 1b)."""
    work = compute_jsts_taint_work(
        graph, scope_id, attrs, run_context=run_context, repo_root=repo_root
    )
    return apply_taint_scope_work(graph, work)

