def _incoming_callers(graph: nx.DiGraph, node_id: str) -> tuple[str, ...]:
    if node_id not in graph:
        return ()
    callers: set[str] = set()
    for u, _, data in graph.in_edges(node_id, data=True):
        if _is_call_edge(data):
            callers.add(str(u))
    return tuple(sorted(callers))

